@js:
const result = [];
if (source.getLoginHeader()) {
    result.push({
        title: ">>> 个人中心 <<<",
        url: null,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: 1
        }
    });
    [
        ["书架", "/api/pc-proxy/api/bff/bookshelf-v1"],
        ["历史记录", "/api/pc-proxy/api/bff/history-v1"]
    ].forEach(([so, path]) => {
        let body = {
            "security_key": source.getLoginHeaderMap()['Cookie'].split('; ')[0].split('=')[1],
            "page": "{{page}}",
            "pageSize": 50
        };

        result.push({
            title: so,
            url: path + ',' + JSON.stringify({
                body: JSON.stringify(body),
                "method": "POST"
            }),
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 0.4
            }
        });
    });
}

[
    ["新书", "/api/pc-proxy/api/bff/home-feed-v1"],
    ["轻小说", "/api/pc-proxy/api/bff/home-lightnovel-feed-v1"],
    ["原创", "/api/pc-proxy/api/bff/home-original-feed-v1"]
].forEach(([sort, path]) => {
    let body = {
        "page": "{{page - 1}}",
        "page_size": 20,
        "pageSize": 20,
        "read_filter": "all",
        "status_filter": "all",
        "category_filter": "all",
        "security_key": source.getLoginHeader() ? source.getLoginHeaderMap()['Cookie'].split('; ')[0].split('=')[1] : ''
    };
    result.push({
        title: '>> ' + sort + ' <<',
        url: null,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: 1
        }
    });
    let tags = JSON.parse(java.post(source.key + path, JSON.stringify(body), {
        "Content-Type": "application/json"
    }).body()).data.filters.category_options;
    tags.forEach((tag, index) => {
        body.category_filter = tag.key;
        result.push({
            title: tag.title,
            url: path + ',' + JSON.stringify({
                body: JSON.stringify(body),
                "method": "POST"
            }),
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: index ? 0.25 : 1
            }
        });
    })
});

JSON.stringify(result);

loginUrl:
function login() {
    let une = source.getLoginInfoMap().get("账号");
    let pwd = source.getLoginInfoMap().get("密码");
    if (une && pwd) {
        let body = JSON.stringify({
            username: une,
            password: pwd
        });
        let url = source.bookSourceUrl+ '/api/pc-proxy/api/bff/auth-password-login-v1';
        let res = java.post(url, body, {
            "Content-Type": "application/json"
        });
        let response = JSON.parse(res.body());
        if (response.code !== 0) {
            java.toast('登录失败，请检查输入信息！');
            return;
        }
        let token = response.data.auth.security_key;
        let header = JSON.stringify({
            "Cookie": `lk_security_key=${token}; lk_uid=${token.split(':')[1]}`
        });
        source.putLoginHeader(header);
    }
}

ruleContent.callBackJs:
let consume = false;
const reading = ['startRead', 'saveRead', 'endRead'];

if (book?.type !== 128 && source.getLoginHeader() && chapter && !chapter.isVolume() && reading.includes(event)) {
    const chapterInfo = JSON.parse(chapter.url.match(/,({.*})$/)[1]).body;
    const { book_id, chapter_id } = JSON.parse(chapterInfo);
    const body = {
        "security_key": source.getLoginHeaderMap()['Cookie'].split('; ')[0].split('=')[1],
        book_id,
        chapter_id,
        "progress_percent": 0,
        "last_position": 0,
        "read_finished": 0
    }
    try {
        let response = java.post(source.key + '/api/pc-proxy/api/new-content-read/save-book-history', JSON.stringify(body), {
        "Content-Type": "application/json"
    }).body();
    if(JSON.parse(response).code === 0) java.log(`进度已同步传至网站\n书籍：${book.name}\n进度：${chapter.title}`);
        consume = true;
    } catch (e) {
        java.log('请求失败' + e.message);
    }
}
consume;

ruleContent.content:
@js:
const data = JSON.parse(src).data;
let content;
if (data.access_type === 'coin' && data.coin_price > 0) {
    content = `${data.body_snapshot.body_text}\n本章节需要 ${data.coin_price} 轻币解锁！`;
} else {
    content = data.render_preview.body_html;
}
content;

ruleContent.payAction:
(() => {
    if (!source.getLoginHeader()) return java.toast('未登录!') || false;
    const chapterInfo = JSON.parse(chapter.url.match(/,({.*})$/)[1]).body;
    const chapter_id = JSON.parse(chapterInfo).chapter_id;
    java.log(chapter_id);
    let body = {
        "security_key": source.getLoginHeaderMap()['Cookie'].split('; ')[0].split('=')[1]
    };
    const headers = {
        "Content-Type": "application/json"
    }
    const userData = JSON.parse(java.post(source.key + '/api/pc-proxy/api/bff/auth-session-v1', JSON.stringify(body), headers).body()).data;
    const userCion = userData.user.balance.coin;
    body.chapter_id = chapter_id;
    const payData = JSON.parse(java.post(source.key + '/api/pc-proxy/api/new-content-read/unlock-chapter', JSON.stringify(body), headers).body()).data;
    if (payData.coin_price === 0) return java.toast('本章节已解锁，无需购买！') || false;
    return java.longToast(`\n解锁成功\n花费 ${payData.coin_price} 轻币\n剩余 ${userCion - payData.coin_price} 轻币`) || true;
})()
